input.sparql:
SELECT ?z ?lbl WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
  FILTER(REGEX(?lbl, "ZN_4|ZN_3|Perimeter"))
}

SELECT ?p ?lbl WHERE {
  ?p a brick:OccupancySensor ; rdfs:label ?lbl .
}

SELECT ?p ?z WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p brick:hasParent ?z .
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  OPTIONAL{?z rdfs:label ?lbl} .
  FILTER(REGEX(str(?z), "Perimeter"))
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  OPTIONAL{?z rdfs:label ?lbl}
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
}

SELECT ?z ?lbl ?c WHERE {
  ?z rdfs:label ?lbl .
  ?z a ?c .
  FILTER(REGEX(?lbl, "Perimeter_top_ZN_4|Perimeter_mid_ZN_3"))
}

SELECT ?z ?lbl ?ts WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?lbl .
  ?p ref:hasExternalReference ?eref .
  ?eref ref:hasTimeseriesId ?ts .
  { ?z ?x ?p } UNION { ?p brick:hasParent ?z }
}

SELECT ?p ?ts ?class WHERE {
  ?p a brick:Occupancy_Sensor .
  ?p ref:hasExternalReference ?eref .
  ?eref ref:hasTimeseriesId ?ts .
  FILTER(str(?p) ~ "Zone_F3_Z02.Occupancy_Sensor|Zone_F4_Z05.Occupancy_Sensor")
}

SELECT ?p ?pred WHERE {
  ?z the? .
}

SELECT ?s ?p ?o WHERE {
  ?s a brick:Occupancy_Sensor .
  ?s ?p ?o .
  FILTER(strcontains(str(?s),"Zone_F4_Z05"))
}

SELECT ?p ?o WHERE {
  ?s a brick:Occupancy_Sensor .
  ?s ?p ?o .
  REGEX(STR(?s), "Zone_F4_Z05") .
}

SELECT ?p ?o WHERE {
  ?s a brick:Occupancy_Sensor .
  ?s ?p ?o .
} FILTER (REGEX(STR(?s), "Zone_F4_Z05"))

SELECT ?p ?o WHERE {
  { ?s a brick:Occupancy_Sensor . ?s ?p ?o } 
  FILTER (REGEX(STR(?s), "Zone_F4_Z05"))
}

SELECT ?s ?ts WHERE {
  { ?s a brick:Occupancy_Sensor . ?s brick:isPointOf ?z . ?s ref:hasExternalReference ?eref . ?eref ref:hasTimeseriesId ?ts }
  FILTER (REGEX(STR(?s), "Zone_F4_Z05"))
}

SELECT ?s ?ts WHERE {
  { ?s a brick:Occupancy_Sensor . ?s brick:isPointOf ?z . ?s ref:hasExternalReference ?eref . ?eref ref:hasTimeseriesId ?ts }
  FILTER (REGEX(STR(?s), "Zone_F3_Z02"))
}
